INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'Biology', 'Unit 6', 'Molarum Grade 10 — Biology Ecological Interactions', 'Source-grounded Molarum Grade 10 Biology questions for Ecological Interactions.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('bb9474b1-71ec-43ef-850b-ddc897798f86'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'Which is the ultimate source of energy for most organisms in ecosystems?', 'The Sun', 'Producers use sunlight to drive photosynthesis, forming the base of most food chains; energy then flows through the ecosystem.', 0),('f7765415-ce57-404c-8418-5e530a9c91d3'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'Which statement best describes energy flow during nutrient recycling in ecosystems?', 'Energy flows in one direction and is lost as heat, while nutrients cycle', 'Matter cycles (nutrients) while energy is dissipated as heat and cannot be recycled; it continues to move through the system.', 1),('8d333275-455f-4a47-8646-812fe61abe5c'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'In the simple food chain grass → rabbit → fox, which statement best describes energy flow?', 'Energy flows from grass to rabbit to fox', 'Energy enters as sunlight captured by producers, then passes to consumers; it generally moves in one direction through the chain.', 2),('8ea74d4b-f4ee-408b-83c3-004f0f076235'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'What happens to most energy when moving from one trophic level to the next?', 'It is lost as heat and used for life processes', 'Energy transfer is inefficient; most energy is dissipated as heat and used for metabolism, not carried forward.', 3),('88308ff9-783f-464a-829e-2204fd17452b'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'Is the flow of energy through ecosystems strictly unidirectional?', 'It is largely unidirectional but some energy is recycled locally within food webs', 'Energy mostly moves from producers to consumers, but detrital pathways and local recycling mean some energy temporarily cycles.', 4),('29363462-3db9-46b5-86da-d8045f056ae3'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'In a simplified energy flow model, producers capture 10,000 kJ/m^2/year. If the transfer efficiency between trophic levels is 10%, calculate the energy available at the primary consumer (herbivore), secondary consumer (first carnivore), and tertiary consumer (second carnivore) per square meter per year. Show your method and final units.', 'Primary: 1000 kJ/m^2/year; Secondary: 100 kJ/m^2/year; Tertiary: 10 kJ/m^2/year', 'Energy at each step = 0.10 × energy at previous level. 10,000 -> 1,000 -> 100 -> 10 (kJ/m^2/year).', 5),('f23577d7-ab3b-4fd3-85a1-12b0f67ede6b'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'Define trophic level in one or two sentences.', 'A trophic level is a position an organism occupies in a food chain based on its main energy source and feeding role (e.g., producers, primary consumers, secondary consumers).', 'Trophic levels categorize organisms by who they eat and who eats them, shaping energy flow.', 6),('718fcf06-3ba2-46d6-8e0e-18cbf3a1e08b'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'true_false', 'True or False: An organism can belong to more than one trophic level depending on its diet.', 'True', 'Many organisms, like omnivores, feed at multiple trophic levels.', 7),('491eb8fa-d807-4d32-84b3-f93a19c04c34'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'Explain the role of decomposers in the flow of energy in ecosystems.', 'Decomposers break down detritus, recycle nutrients, and release energy as heat; they connect dead organic matter back into the ecosystem, enabling producers to re-enter the cycle.', 'Decomposers are essential for nutrient recycling and maintaining energy flow through detrital pathways.', 8),('fd1aa7e5-ee7c-41e6-805b-9fe0207ff666'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'Using the same 24,000 kJ/m^2/year producer energy and 15% transfer efficiency between levels as in Q006, calculate the energy at primary, secondary, and tertiary levels (in kJ/m^2/year). Show your method and final units.', 'Primary: 3600 kJ/m^2/year; Secondary: 540 kJ/m^2/year; Tertiary: 81 kJ/m^2/year', 'Energy at each step = 0.15 × energy at previous level: 24,000 -> 3,600 -> 540 -> 81 (kJ/m^2/year).', 9),('2ef13907-6f8d-4685-81f3-e6d852086655'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'Based on Figure 6.1 Schematic illustrations of the food chain and food web, which statement best describes a food chain?', 'A) A linear sequence showing who eats whom', 'A food chain shows a straight-line sequence of who eats whom; a food web shows multiple, interconnected feeding relationships.', 10),('1e6c3de6-dd0a-406c-8979-1498abfb5543'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'In a food chain, which trophic level is represented by the primary consumer?', 'B) Primary consumers', 'Primary consumers are herbivores that feed on producers.', 11),('9840e1e5-ac66-4dfd-8ceb-c179813e154e'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'What happens to energy as it moves from a producer to a primary consumer?', 'C) It is transferred, with some energy lost as heat', 'Energy is transferred between trophic levels, but much is lost as heat during metabolism and other processes.', 12),('96a24bda-e732-4e07-8235-54bfb1273559'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'Which trophic level is a secondary consumer?', 'C) Secondary consumer', 'Secondary consumers are the organisms that eat primary consumers.', 13),('b3106d32-1bc0-4334-8f19-7d3b1148ec86'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'Which statement about energy flow in ecosystems is correct?', 'C) Energy flows unidirectionally and is largely lost as heat', 'Energy flow is unidirectional through the trophic levels and much of it is lost as heat; matter can cycle.', 14),('dcbd38a0-304e-432e-8c53-f0d11e82d123'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'List one key difference between energy flow and matter cycling in ecosystems.', 'Energy flows in one direction and is lost as heat; matter cycles within the ecosystem.', 'Energy moves through the ecosystem and is typically lost as heat at each transfer; matter (nutrients) is recycled through cycles such as carbon, nitrogen, and water cycles.', 15),('2ae10d71-8d4b-4d19-80fd-893bd93b4a5b'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'Explain why the energy transferred to the next trophic level is less than the energy at the previous level.', 'Energy is used for metabolism, growth, and daily activities; only a portion is assimilated by the next level, the rest is lost as heat or uneaten.', 'Energy transfers are inefficient; metabolic costs and heat losses mean less energy is available to the next trophic level.', 16),('29ab0b51-04e2-4182-81cf-aa49c21418ac'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'In a hypothetical ecosystem, producers capture 2000 kJ/m^2/day of solar energy. If energy transfer from producers to primary consumers is 10%, how much energy is available to the primary consumer per square meter per day? Provide the value with units and show your method.', '200 kJ/m^2/day', 'Energy to the primary consumer = 2000 kJ/m^2/day × 0.10 = 200 kJ/m^2/day. Final unit: kJ/m^2/day.', 17),('d5c37a19-f3ce-4bae-84db-6b249ea71ccf'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'In a simplified ecosystem, producers store 5000 kJ/m^2/day. If energy transfer to the primary consumer is 10% and from the primary to the secondary consumer is 10% of the energy at the previous level, how much energy is available to the secondary consumer per m^2 per day? Show all steps and give the final unit.', '50 kJ/m^2/day', 'Primary energy = 5000 × 0.10 = 500 kJ/m^2/day. Secondary energy = 500 × 0.10 = 50 kJ/m^2/day.', 18),('0252d157-46d4-4f21-846f-9d1a13ba91e1'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'true_false', 'Field observations of ecological interactions show that energy flow in ecosystems is strictly linear with no energy losses.', 'False', 'Energy flows from producers to consumers and is largely lost as heat at each transfer; it is not strictly linear with no losses.', 19),('61af70bd-e894-448e-805f-bc630cf3c56c'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'What is a trophic level?', 'A) The position an organism occupies in a food chain', 'A trophic level is the position an organism occupies in the transfer of energy through feeding relationships.', 20),('622deb1c-e2ad-468e-8d88-117715e241b0'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'Energy flow in a food chain typically moves', 'C) in one direction from producers to higher-level consumers', 'Energy flows from producers through successive consumers in a single direction; it is not recycled.', 21),('0d664447-a59d-4065-8945-c98ae594bd00'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'true_false', 'Is it the unidirectional flow of energy that is commonly observed in an ecosystem?', 'True', 'Energy generally flows in one direction from producers to higher trophic levels; it is not recycled in ecosystems.', 22),('34948460-c66e-4838-886d-11751e6f1baf'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'What happens to most of the energy as it moves from one trophic level to the next?', 'B) It is transmitted as heat and only about 10% is transferred', 'About 90% is lost as heat and used in metabolism; roughly 10% is transferred to the next trophic level.', 23),('ad48179c-a2ae-4002-8213-a5950078bc9f'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'Which statement best describes energy flow during nutrient recycling in an ecosystem?', 'C) Energy flows in one direction and is not recycled', 'Energy flows in one direction through the ecosystem and is not recycled; matter is recycled.', 24),('6ac59ad1-f18a-456b-8660-b60e5c76fbc5'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'Explain the difference between a trophic level and a feeding level, and provide one example.', 'A trophic level is the position of an organism in the energy transfer sequence in a food chain (example: producers are the first trophic level). A feeding level is a general description of where an organism feeds; trophic level specifies energy transfer in the chain.', 'Trophic level denotes energy transfer position; feeding level is a functional feeding role. Example: Producers = first trophic level.', 25),('dfce7924-9e1a-41be-8f9b-0002ff0c1c05'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'If a producer captures 12,000 kJ of energy from the sun, and only 10% is transferred to the first consumer, how many kJ are available to the primary consumer? Show your calculation and final unit.', '1,200 kJ', 'Energy transfer between trophic levels is about 10%, so 12,000 kJ × 0.10 = 1,200 kJ.', 26),('dd8fe4c6-74f9-4128-8231-fa01411df3fd'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'In a simple food chain, producers receive 50,000 kJ of energy from the sun. If 10% is transferred to the primary consumer and another 10% to the secondary, how much energy is available to the tertiary consumer? Show calculations and final unit.', '50 kJ', 'Apply 10% rule at each transfer: 50,000 × 0.10 = 5,000 to primary; 5,000 × 0.10 = 500 to secondary; 500 × 0.10 = 50 to tertiary.', 27),('bbe65e84-7749-4acc-88b7-75e0d4f4dc2d'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'What is the ultimate source of energy in life? How is energy transferred from organism to organism?', 'B) The Sun', 'Sunlight captured by producers provides the energy that moves through the food chain.', 28),('722a3ac4-d537-4bd2-89df-6103f77750e8'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'Explain why energy transfer between trophic levels is inefficient and name two ecological consequences.', 'Energy transfer is inefficient because only about 10% of energy is passed to the next trophic level, the rest is lost as heat and used in metabolism; consequences include biomass decline at higher levels and limitation on the number of trophic levels.', 'The 10% rule explains energy loss; biomass decreases at higher trophic levels; ecosystems rely on large energy input at base.', 29),('afdf4a50-3b07-4118-866c-9d6e66984ffb'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'In a simple ecosystem, which organism most accurately represents the first trophic level?', 'A producer', 'Producers form the base of the food chain and occupy the first trophic level.', 30),('5f01f07e-82ff-45fa-849f-93be03d09ab1'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'Which statement about energy flow in ecosystems is generally true?', 'Energy flows in one direction from producers to higher trophic levels.', 'Energy enters as sunlight and flows through organisms, with most energy lost as heat at each transfer.', 31),('64ee019b-260a-4d71-84bc-a4c8489372cc'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'Which of the following best describes a food chain?', 'A single path of energy transfer stretching from producers to top-level consumers.', 'A food chain is a linear sequence illustrating energy transfer from producers to higher levels; a food web shows multiple connections.', 32),('aac1cbac-123a-490e-8ceb-8e6ccba9a622'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'Approximately what percentage of energy is transferred from one trophic level to the next in most ecosystems?', '10%', 'On average about 10% of the energy at one level is passed to the next; the rest is lost as heat and metabolic processes.', 33),('061eb588-93c3-47b3-8f51-fe36cb0af815'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'multiple_choice', 'What is the primary difference between a food chain and a food web?', 'A food chain shows a single linear path; a food web shows multiple interconnected paths.', 'Food webs represent many feeding relationships; a chain is a simplified, linear sequence of feeding relations.', 34),('52f0ae91-35f1-4583-844c-e6be8eb01854'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'In a two-trophic-level system, if producers receive 7000 kJ/m^2/year of energy and 10% is transferred to primary consumers, how much energy is available to the primary consumer per year? Show calculation and final units.', '700 kJ/m^2/year', 'Energy to Primary Consumer = 0.10 × 7000 kJ/m^2/year = 700 kJ/m^2/year.', 35),('ad151025-95df-45c4-8c64-43dc12fe8259'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'In a four-level food chain with energy transfer efficiency of 10% per level, if producers have 50,000 kJ/m^2/year, compute energy at each level: producers, primary consumer, secondary consumer, and tertiary consumer. Provide step-by-step and final unit.', 'Producer: 50,000 kJ/m^2/year; Primary: 5,000 kJ/m^2/year; Secondary: 500 kJ/m^2/year; Tertiary: 50 kJ/m^2/year', 'Each level is 10% of the previous: 50,000 → 5,000 → 500 → 50 kJ/m^2/year.', 36),('df28619f-c2a6-42fa-866d-f23204b061d1'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'Briefly describe the ultimate source of energy in life and how energy is transferred from one organism to another in an ecosystem.', 'The sun is the ultimate energy source; energy is transferred through producers to consumers via feeding relationships, with energy lost as heat at each transfer.', 'Energy enters ecosystems as solar radiation, is captured by producers (photosynthesis), and is passed along food chains/webs with substantial losses as heat.', 37),('3ef8ea92-7482-4d4b-8f36-4e2ab9ad365b'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'fill_blank', 'Define a producer and give one terrestrial example.', 'A producer is an organism that makes its own food using photosynthesis; example: grass.', 'Producers form the base of the food chain by converting solar energy into chemical energy.', 38),('9014206b-a6a2-4951-8ff8-59654e1f4945'::uuid, '23534396-71c6-499d-8832-ed95469e49e9'::uuid, 'true_false', 'Energy is recycled and reused within an ecosystem.', 'False', 'Energy flows through ecosystems in one direction and is lost as heat at each transfer; it is not recycled.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
