ee-408b-83c3-004f0f076235'::uuid, 'It is lost as heat and used for life processes', TRUE, 1),('636adec6-2c23-47e5-8623-0cbe6165adb3'::uuid, '8ea74d4b-f4ee-408b-83c3-004f0f076235'::uuid, 'It disappears', FALSE, 2),('ea81e1e4-e97d-433d-8bc8-058369b9962c'::uuid, '8ea74d4b-f4ee-408b-83c3-004f0f076235'::uuid, 'It increases in quantity', FALSE, 3),('b5004d89-bb1d-4935-84d2-fa0e09aefe52'::uuid, '88308ff9-783f-464a-829e-2204fd17452b'::uuid, 'Yes, always', FALSE, 0),('a8320a39-9def-4b3c-85a8-35bc91cc6641'::uuid, '88308ff9-783f-464a-829e-2204fd17452b'::uuid, 'No, energy cycles completely', FALSE, 1),('f9ed76b1-9f1e-4a12-8776-ba7cc22f3f79'::uuid, '88308ff9-783f-464a-829e-2204fd17452b'::uuid, 'It is largely unidirectional but some energy is recycled locally within food webs', TRUE, 2),('0c036d7a-2945-4088-8d8f-ed1c5a1a8d3b'::uuid, '88308ff9-783f-464a-829e-2204fd17452b'::uuid, 'Energy flows only within producers', FALSE, 3),('87315545-f242-4375-8d1d-b8c07266e316'::uuid, '718fcf06-3ba2-46d6-8e0e-18cbf3a1e08b'::uuid, 'True', TRUE, 0),('cb951d65-c309-4ca7-81fa-67e2e6292983'::uuid, '718fcf06-3ba2-46d6-8e0e-18cbf3a1e08b'::uuid, 'False', FALSE, 1),('76df5073-d50c-4993-847f-b0e64bf520bb'::uuid, '2ef13907-6f8d-4685-81f3-e6d852086655'::uuid, 'A) A linear sequence showing who eats whom', TRUE, 0),('f3c6f458-f54d-41a1-8db5-fc60134d6698'::uuid, '2ef13907-6f8d-4685-81f3-e6d852086655'::uuid, 'B) A network of overlapping feeding relationships', FALSE, 1),('badaef1e-e7d2-4650-81e1-2e5bdc184d15'::uuid, '2ef13907-6f8d-4685-81f3-e6d852086655'::uuid, 'C) A diagram of nutrient cycling', FALSE, 2),('484fda06-ea48-43f4-848f-04259739375b'::uuid, '2ef13907-6f8d-4685-81f3-e6d852086655'::uuid, 'D) A model of energy production by producers', FALSE, 3),('b5d89026-6915-4938-85ff-dfddfaabd06f'::uuid, '1e6c3de6-dd0a-406c-8979-1498abfb5543'::uuid, 'A) Producers', FALSE, 0),('f703b5a2-12d2-46c2-8b4b-210d98239f70'::uuid, '1e6c3de6-dd0a-406c-8979-1498abfb5543'::uuid, 'B) Primary consumers', TRUE, 1),('a62d3ea9-eff